#!/usr/bin/env python3
# Summarise hole classes from the CLASS=1 outputs (<tag>.cls.txt) and the start S (<tag>.sol.start).
# Class priority: central (scalar) > involution (projective order 2 with z = 0) > alpha (fixed by conj AG) > other.
# torus = canonical trace (min(t,p-t)) of the hole equals that of some power of a generator S_j (j >= 1),
# i.e. the hole lies in a torus (conjugacy class) generated by a generator of S.
import glob, os, re, sys
E13 = os.path.dirname(os.path.abspath(__file__))
HOLE = re.compile(r"HOLE side=(\w) class=(\w+) z=(\d+) mat\((-?\d+),(-?\d+),(-?\d+),(-?\d+)\) trace=(\d+) order=(\d+) index=(\d+)")
def ctr(t, p): return min(t % p, (-t) % p)
def gen_traces(path, p):
    S = []
    for line in open(path):
        m = re.search(r"mat\((-?\d+),(-?\d+),(-?\d+),(-?\d+)\)", line)
        if m: S.append(tuple(int(x) % p for x in m.groups()))
    out = set()
    for (a, b, c, d) in S[1:]:
        x = (1, 0, 0, 1); cur = (a, b, c, d)
        for k in range(1, 2 * p + 8):
            out.add(ctr(cur[0] + cur[3], p))
            if cur[0] == 1 and cur[1] == 0 and cur[2] == 0 and cur[3] == 1: break
            cur = ((cur[0]*a + cur[1]*c) % p, (cur[0]*b + cur[1]*d) % p, (cur[2]*a + cur[3]*c) % p, (cur[2]*b + cur[3]*d) % p)
    return out, len(S)
rows = []
for cls_file in sorted(glob.glob(os.path.join(E13, "*.cls.txt"))):
    tag = os.path.basename(cls_file)[:-len(".cls.txt")]
    m = re.match(r"(sl|psl)(\d+)_n(\d+)_s(\d+)", tag)
    if not m: continue
    fam, p, n, seed = m.group(1), int(m.group(2)), int(m.group(3)), int(m.group(4))
    txt = open(cls_file).read()
    if "CLASS side" not in txt: continue
    gt, nS = gen_traces(os.path.join(E13, tag + ".sol.start"), p)
    cnt = {"central": 0, "involution": 0, "alpha": 0, "other": 0}; tor = 0; ords = {}; sides = {}
    for mm in HOLE.finditer(txt):
        side, cl, z, a, b, c, d, tr, order, idx = mm.groups()
        z = int(z); tr = int(tr); order = int(order)
        sides[side] = sides.get(side, 0) + 1
        if cl == "central": k = "central"
        elif order == 2 and z == 0: k = "involution"
        elif cl == "alpha": k = "alpha"
        else: k = "other"
        cnt[k] += 1
        if k == "other" and order in ((p - 1) // 2, (p + 1) // 2, p): tor += 1
        ords[order] = ords.get(order, 0) + 1
    tot = sum(cnt.values())
    top = sorted(ords.items(), key=lambda kv: -kv[1])[:3]
    rows.append((fam, p, n, seed, tot, cnt, tor, sides, top))
print("| group | seed | holes | central | involution | alpha | other | other with order (p-1)/2, (p+1)/2 or p | side | top projective orders |")
print("|---|---|---|---|---|---|---|---|---|---|")
for fam, p, n, seed, tot, cnt, tor, sides, top in sorted(rows, key=lambda r: (r[0], r[1], r[2], r[3])):
    g = f"{fam.upper()}({2 if False else ''}{p}) x Z{n}"
    print(f"| {fam.upper()}(2,{p}) x Z_{n} | {seed} | {tot} | {cnt['central']} | {cnt['involution']} | {cnt['alpha']} | {cnt['other']} | {tor} | {','.join(sorted(sides))} | {' '.join(f'{o}:{c}' for o,c in top)} |")
